using Myriale.Api.Architecture; namespace Myriale.Api.Features.ModuleExecutions; [FeatureSlice("ModuleExecutions")] public static class ModuleExecutionsFeature { public static IServiceCollection AddModuleExecutionsFeature(this IServiceCollection s,IConfiguration c){s.Configure<ModuleExecutionOptions>(c.GetSection(ModuleExecutionOptions.SectionName));s.AddScoped<SessionOutcomeEffectService>();s.AddScoped<IModuleExecutionRepository,EfModuleExecutionRepository>();s.AddScoped<IModuleExecutionProjection,ModuleExecutionProjection>();s.AddScoped<IModuleExecutionUiBindingReader,EfModuleExecutionUiBindingReader>();s.AddScoped<IModuleExecutionWorkflow,ModuleExecutionWorkflow>();s.AddScoped<InitializeDetachedModuleExecutionCommand>();s.AddScoped<InitializeSessionTurnModuleExecutionCommand>();s.AddScoped<IModuleExecutionInitializer,ModuleExecutionInitializer>();s.AddScoped<DispatchModuleExecutionCommand>();s.AddScoped<GetModuleExecutionQuery>();return s;} public static IEndpointRouteBuilder MapModuleExecutionsFeature(this IEndpointRouteBuilder e){e.MapModuleExecutionEndpoints();return e;} }
